      explicitPath ??
      (tracker != null
          ? tracker.buildLeafPath(extraSegment)
          : (extraSegment != null ? <Object>[extraSegment] : const <Object>[]));
  final ex = CodableException(
    message,
    path: List<Object>.unmodifiable(path),
    actualValue: actualValue,
    underlyingError: underlyingError,
