    final path = List<Object>.unmodifiable(
      _tracker != null ? _tracker.buildLeafPath() : const <Object>[],
    );
    final enriched = CodableException(
      e.message,
      path: path,
      actualValue: e.actualValue,
      underlyingError: e.underlyingError,
    );
    _tracker?.record(enriched);
    return enriched;
