  @pragma('wasm:prefer-inline')
  Decoder keyDecoder() {
    if (!_hasActiveEntry) _throwNoActiveEntry();
    _tracker?.setInChild(_frame, false);
    return _keyDecoder;
  }

  @override
  @pragma('vm:prefer-inline')
  @pragma('wasm:prefer-inline')
  Decoder valueDecoder() {
    if (!_hasActiveEntry) _throwNoActiveEntry();
    _tracker?.setInChild(_frame, true);
